import { JSX, ParentComponent } from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

/** Props for {@link InnerFrame}. */
export type InnerFrameProps = JSX.HTMLAttributes<HTMLDivElement>;

const InnerFrameComponent: ParentComponent<InnerFrameProps> = (props) => {
	return (
		<div
			{...props}
			class={`fxs-inner-frame inner-frame relative flex flex-col items-center ${props.class ?? ""}`}
		>
			{/* Decorative overlay matching legacy inner frame filigree */}
			<div class="absolute inset-0 pointer-events-none">
				<div class="absolute top-0 inset-x-0 filigree-inner-frame-top" />
				<div class="absolute bottom-0 inset-x-0 filigree-inner-frame-bottom" />
			</div>

			{props.children}
		</div>
	);
};

/**
 * An inner frame wrapper used inside other frames and panels.
 * Solid.js reimplementation of the legacy <fxs-inner-frame> component.
 *
 * Usage:
 * <InnerFrame class="mx-6 my-1.5"> ... </InnerFrame>
 */
export const InnerFrame = ComponentRegistry.register({
	name: "InnerFrame",
	createInstance: InnerFrameComponent,
});
